const fs = require('node:fs');
const files = (await $`grep -rlE "retryPolicy|maxAttempts: 3" src test`).stdout.trim().split('\n');
for (const f of files) {
  const s = fs.readFileSync(f, 'utf8').replace(/retryPolicy/g, 'backoffPolicy').replace(/maxAttempts: 3/g, 'maxAttempts: 5');
  fs.writeFileSync(f, s);
}
const left = await $`grep -rnE "retryPolicy|maxAttempts: 3" src test`;
const t = await $`node --test 2>&1`;
